work_descriptions","ref":"description:42","key":{"work_id":977100057,"language":"nl"},"before":null,"after":{"work_id":977100057,"language":"nl","bound_author_id":977300031,"text":"Anna Karenina leeft binnen de verwachtingen van de Russische adel wanneer zij verliefd wordt op een man die niet haar echtgenoot is. Haar keuze brengt de verhoudingen in haar omgeving en haar eigen bestaan onder druk. De roman verbindt haar ervaringen met andere levens en laat verschillende opvattingen over liefde, huwelijk en plicht naast elkaar bestaan. Zo wordt zichtbaar hoe persoonlijke verlangens botsen met sociale en morele oordelen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/129679/anna-karenina.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-07-20261101","evidence":[{"url":"https://metadata.isbn.nl/129679/anna-karenina.html","sha256":"c02023a21148607bdc7bc050ae379d7a7a11c4ac9188c14459a3605c56452095","checkedAt":"2026-11-01T14:12:24.213Z","fact":"Hardback ISBN 9789025301583 verschijningsdatum 31/01/2017 NUR 302 Vertaalde literaire roman, novelle imprint Athenaeum - Polak & van Gennep uitgever Singel Uitgeverijen taal Nederlands","sourceAuthors":"Lev Tolstoi","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"works","ref":"work:new-schemerleven","key":{"id":977100101},"before":null,"after":{"native_identity_key":"nl-reviewed-isbn:9789044549874","title":"Schemerleven","author_id":977300032,"open_library_id":null,"source_type":"lumiscore_native","work_type":null,"first_publish_year":2022,"cover_id":null,"id":977100101}},{"relation":"editions","ref":"edition:9789044549874","key":{"id":977200145},"before":null,"after":{"work_id":977100101,"title":"Schemerleven","language":"nld","isbn_13":"9789044549874","isbn_10"